function Gallery({rows,loading,profilePath,partyControls,workflow,workflowError,onWorkflowUpdate}:{rows:Resident[];loading:boolean;profilePath:string;partyControls:boolean;workflow:Record<string,WorkflowSummary>;workflowError:string;onWorkflowUpdate:(id:string|number,summary:WorkflowSummary)=>void}){
 const [selected,setSelected]=useState<Resident|null>(null);
 if(loading)return <div className="grid grid-cols-1 gap-4 p-4 md:grid-cols-2 2xl:grid-cols-3">{Array.from({length:6}).map((_,i)=><div key={i} className="h-72 animate-pulse rounded-xl bg-primary-light"/>)}</div>;
 if(!rows.length)return <div className="empty-state m-5">No residents found.</div>;
 return <><div className="grid grid-cols-1 gap-4 p-4 md:grid-cols-2 2xl:grid-cols-3">{rows.map(r=>partyControls?<ResidentFlipCard key={String(r.id)} resident={r} profilePath={profilePath} partyControls workflow={workflow[String(r.id)]} workflowError={workflowError}/>:<ResidentGalleryCard key={String(r.id)} resident={r} profilePath={profilePath} workflow={workflow[String(r.id)]} workflowError={workflowError} showRemark={new URLSearchParams(window.location.search).get('focus')==='remarks'} onViewTasks={()=>setSelected(r)}/>)}</div>{selected&&<ResidentTaskDialog resident={selected} profilePath={profilePath} workflow={workflow[String(selected.id)]} workflowError={workflowError} onWorkflowUpdate={onWorkflowUpdate} onClose={()=>setSelected(null)}/>}</>
}
